import { useState } from 'react';
import Botao from '../Botao';
import CampoTexto from '../CampoTexto'
import ListaSuspensa from '../ListaSuspensa'
import './Formulario.css'

const Formulario = (props) => {

     const [nome, setNome] = useState('');
     const [cargo, setCargo] = useState(''); //os quatro estados
     const [imagem, setImagem] = useState('');
     const [time, setTime] = useState('');

     const aoSalvar = (evento) =>{
          evento.preventDefault() //previne o comportamento padrão
          props.aoColaboradorCadastrado({
               nome: nome,//no JS nao precisa fazer assim para atribuir se os nomesforem iguais pode ser assim so uma propriedade:
               cargo,
               imagem,
               time
          })

          setNome('');
          setCargo('');
          setImagem('');
          setTime('');
     }

     return (
          <section className="formulario">
               <form onSubmit={aoSalvar}>
                    <h2>Preencha os dados para criar o card do colaborador</h2>
                    <CampoTexto obrigatorio={true} label="Nome" placeholder="Digite seu nome" valor={nome} aoAlterado={valor => setNome(valor)} />
                    <CampoTexto obrigatorio={true} label="Cargo" placeholder="Digite seu cargo" valor={cargo} aoAlterado={valor => setCargo(valor)} />
                    <CampoTexto label="Imagem" placeholder="Digite o endereço da imagem" valor={imagem} aoAlterado={valor => setImagem(valor)} />
                    <ListaSuspensa obrigatorio={true} label="Time" itens={props.times} valor={time} aoAlterado={valor => setTime(valor)}/>
                    <Botao>Criar Card</Botao>
               </form>
          </section>
     ) //<Botao texto="Criar Card"/>foi trocado para pegar o elemento filho
}

export default Formulario
